namespace CSharpPracticum.Tasks.Level2;
internal class Task22_Params:ITask{public string Title=>"Задание 22: params-метод + перегрузка";public string Description=>"Реализовать сумму чисел с params и для массива.";public string[] Requirements=>new[]{"Sum(params int[] numbers) суммирует произвольное число аргументов.","Показать Sum(1,2,3), Sum(new[]{1,2,3}) и Sum().","Пустой вызов возвращает 0."};private static int Sum(params int[] numbers){int s=0;foreach(int n in numbers)s+=n;return s;}public void Run(){Console.WriteLine(Sum(1,2,3));Console.WriteLine(Sum(new[]{1,2,3}));Console.WriteLine(Sum());}}
